func tl23(a *tslabs, v any) []*Decorator {
	a.stepWork()
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []*Decorator{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl23Chunk, len(n.kids))
	for i, c := range n.kids {
		a.stepWork()
		out[i] = tAs[*Decorator](c)
	}
	return out
}

